Definition test_neon_safety_wit_1 := 
forall (params_pre: Z) (output_pre: Z) (input_pre: Z) (batch_pre: Z) (A: (@list fp32)) (PreH1 : (0 < batch_pre)) (PreH2 : (batch_pre <= UINT64_MAX)) (PreH3 : ((batch_pre % ( 4 ) ) = 0)) (PreH4 : (input_pre <> 0)) (PreH5 : (output_pre <> 0)) ,
  ((( &( "batch" ) )) # UInt64  |-> batch_pre)
  **  ((( &( "input" ) )) # Ptr  |-> input_pre)
  **  ((( &( "output" ) )) # Ptr  |-> output_pre)
  **  ((( &( "params" ) )) # Ptr  |-> params_pre)
  **  (FloatArray.full input_pre ((batch_pre ÷ 4 ) + 3 ) A )
  **  (FloatArray.undef_full output_pre (batch_pre ÷ 4 ) )
|--
  “ (0 <= INT_MAX) ” 
  &&  “ ((INT_MIN) <= 0) ”
.

